package streamix.readingcatalog
import org.jsoup.Jsoup
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertNull
import kotlinx.coroutines.runBlocking
class AdditionalIndonesianManhwaRuntimeProviderTest2 {
 @Test fun manhwaListUsesReaderArea()=runBlocking{val p=ManhwaListReadingRuntimeProvider{u->Jsoup.parse("""<div id="readerarea"><img data-src="/p.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://m1.manhwalist.my.id/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","manhwa-list","https://m1.manhwalist.my.id/chapter/title")));assertEquals(listOf("https://m1.manhwalist.my.id/p.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun manhwaListFallsBackToDataOriginalAndSkipsDataUri()=runBlocking{val p=ManhwaListReadingRuntimeProvider{u->Jsoup.parse("""<div id="readerarea"><img data-lazy-src="data:image/gif;base64,placeholder" data-original="/original.jpg"></div>""",u)};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://m1.manhwalist.my.id/series/title",ReadingEntryOrigin.MANUAL);val ch=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","manhwa-list","https://m1.manhwalist.my.id/chapter/title")));assertEquals(listOf("https://m1.manhwalist.my.id/original.jpg"),p.chapter(e,ch)?.pageUrls)}
 @Test fun cosmicScansUsesReadingPageApi()=runBlocking{var url="";val p=CosmicScansIdReadingRuntimeProvider{u->url=u;"""{"data":{"chapters":["<div><img src='https://cdn.cosmicscans.to/1.jpg'></div>"]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://02.cosmicscans.to/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","cosmicscans","https://02.cosmicscans.to/series/title/chapter/123")));assertEquals(true,p.supports(e,c));val result=p.chapter(e,c);assertEquals("https://cdncid.csmcscns.id/v1/manga/readingPage/123",url);assertEquals(listOf("https://cdn.cosmicscans.to/1.jpg"),result?.pageUrls)}
 @Test fun rejectsNonCanonicalHost()=runBlocking{val p=ManhwaListReadingRuntimeProvider{error("must not fetch")};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://m1.manhwalist.my.id/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","manhwa-list","https://evil.example/chapter/1")));assertFalse(p.supports(e,c));assertNull(p.chapter(e,c))}
 @Test fun cosmicScansExtractsEveryImageFromHtmlPagePayload()=runBlocking{val p=CosmicScansIdReadingRuntimeProvider{"""{"data":{"chapters":["<div><img src=https://cdn.cosmicscans.to/1.jpg><img data-original=https://cdn.cosmicscans.to/2.jpg></div>"]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://02.cosmicscans.to/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","cosmicscans","https://02.cosmicscans.to/series/title/chapter/123")));assertEquals(listOf("https://cdn.cosmicscans.to/1.jpg","https://cdn.cosmicscans.to/2.jpg"),p.chapter(e,c)?.pageUrls)}
 @Test fun cosmicScansRejectsRedirectPayload()=runBlocking{val p=CosmicScansIdReadingRuntimeProvider{"""{"data":{"redirectLink":"https://other.example","chapters":["<img src='https://cdn.example/p.jpg'>"]}}"""};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://02.cosmicscans.to/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","cosmicscans","https://02.cosmicscans.to/series/title/chapter/123")));assertNull(p.chapter(e,c))}
 @Test fun cosmicScansRejectsOldHost()=runBlocking{val p=CosmicScansIdReadingRuntimeProvider{error("must not fetch")};val e=ReadingCatalogEntry("m",ReadingKind.MANHWA,"M","https://02.cosmicscans.to/series/title",ReadingEntryOrigin.MANUAL);val c=ReadingChapterEntry("c","1",sources=listOf(ReadingChapterSource("s","cosmicscans","https://04.cosmicscans.to/series/title/chapter/123")));assertFalse(p.supports(e,c));assertNull(p.chapter(e,c))}
}
